ENR[3] = {
 'Main invisible et division du travail': {
  'ti': 'La division du travail, source première de la productivité',
  'af': "Smith soutient que l'origine première de l'enrichissement des nations n'est ni l'accumulation de métal précieux ni la fertilité du sol, mais la division du travail. Sa thèse est que décomposer une production en opérations élémentaires confiées à des travailleurs différents accroît la quantité produite dans des proportions sans commune mesure avec l'effort fourni. Trois raisons l'expliquent, qu'il énonce explicitement : l'ouvrier qui répète une même opération acquiert une dextérité supérieure ; il n'a plus à perdre de temps à passer d'une tâche à l'autre, ni à changer d'outil et de posture ; enfin, une tâche devenue simple et répétitive peut être confiée à une machine, ce qui ouvre la voie à la mécanisation. Smith ajoute une condition décisive : la division du travail est limitée par l'étendue du marché, car une spécialisation poussée suppose des débouchés assez vastes pour absorber la production.",
  'me': "Le raisonnement progresse en trois temps. Premièrement, la spécialisation élève la productivité par les trois canaux énoncés — dextérité, suppression des temps morts, mécanisation —, ce que Smith illustre par un calcul : la manufacture d'épingles, en répartissant dix-huit opérations distinctes entre autant d'ouvriers, produit des milliers d'épingles par jour là où un artisan isolé en produirait quelques dizaines. Deuxièmement, cette hausse de productivité abaisse le coût unitaire, donc le prix, donc élargit le marché accessible. Troisièmement, le marché élargi autorise une division du travail encore plus poussée : le mécanisme est cumulatif. Mais la relation vaut aussi en sens inverse, et c'est là que l'argument devient un argument en faveur de l'échange : un marché étroit plafonne la spécialisation possible, de sorte que l'ouverture commerciale n'est pas un simple supplément de débouchés, elle conditionne le niveau de productivité atteignable.",
  'ex': "La manufacture d'épingles : étirer le fil, le dresser, le couper, en aiguiser la pointe, préparer la tête, l'ajuster, blanchir, empaqueter — dix-huit opérations distinctes dont la répartition entre dix ouvriers permet une production par tête plusieurs centaines de fois supérieure à celle d'un artisan accomplissant seul la totalité du processus.",
  'po': "Dans le chapitre, cette idée inaugure l'analyse classique et fournit la première explication théorique de l'enrichissement : la richesse est un flux produit par le travail organisé, et non un stock à conquérir, ce qui rompt frontalement avec le mercantilisme exposé juste avant. Elle introduit en outre la productivité comme concept central, dont dépendra toute l'analyse ultérieure de la croissance.",
  'co': "Comme le montre Adam Smith dans la Richesse des nations (1776), la division du travail accroît la productivité par trois canaux — la dextérité acquise par la répétition, la suppression des temps de passage d'une tâche à l'autre et la possibilité de mécaniser des opérations devenues simples — mais elle demeure limitée par l'étendue du marché.",
 },
 'Avantages comparatifs et rendements décroissants': {
  'ti': 'Avantages comparatifs et spécialisation',
  'af': "Ricardo soutient qu'un pays a intérêt à se spécialiser et à échanger même lorsqu'il produit tous les biens moins efficacement que son partenaire, ce qui constitue l'un des résultats les plus contre-intuitifs de l'analyse économique. Sa thèse repose sur un déplacement du critère : ce qui détermine l'intérêt d'une spécialisation n'est pas la productivité absolue mais le coût d'opportunité, c'est-à-dire ce à quoi il faut renoncer pour produire une unité supplémentaire d'un bien. Chaque pays doit se spécialiser là où ce sacrifice est le plus faible, c'est-à-dire là où il détient un avantage comparatif, puis échanger le reste. Le résultat est que la production mondiale augmente à ressources inchangées et que les deux partenaires peuvent consommer davantage qu'en autarcie. Ricardo établit ainsi que l'échange international n'est pas un jeu à somme nulle, contrairement à ce que soutenaient les mercantilistes.",
  'po': "Dans le chapitre, cette démonstration achève de renverser l'analyse mercantiliste de l'échange et fournit le fondement théorique du libre-échange, qui sera discuté tout au long du programme. Elle montre aussi la méthode classique à l'œuvre : un raisonnement déductif, construit sur des hypothèses explicites, dont la portée est exactement délimitée par ces hypothèses.",
  'co': "Ricardo établit dans les Principes (1817) qu'un pays gagne à la spécialisation même sans avantage absolu : c'est le coût d'opportunité, et non la productivité absolue, qui détermine l'avantage comparatif, de sorte que l'échange accroît la production mondiale à ressources inchangées.",
 },
 'Piège malthusien : population et subsistances': {
  'af': "Malthus soutient que la population tend à croître plus vite que les moyens de subsistance, de sorte que toute amélioration du niveau de vie est à terme annulée par l'accroissement du nombre d'hommes. La thèse repose sur une asymétrie de rythmes : la population, lorsqu'elle n'est pas freinée, croît selon une progression géométrique, tandis que la production alimentaire, limitée par la quantité et la qualité des terres disponibles, ne peut croître que selon une progression arithmétique. Il en résulte un retour permanent vers le niveau de subsistance, assuré par deux catégories de freins : les freins positifs, qui élèvent la mortalité — famine, épidémie, guerre — et les freins préventifs, qui abaissent la natalité, au premier rang desquels Malthus place le report du mariage et la contrainte morale. Sa conclusion est pessimiste et explicitement dirigée contre les projets d'amélioration générale de la condition des pauvres.",
  'po': "Dans le chapitre, cette thèse illustre le versant pessimiste de l'analyse classique et introduit la question des limites physiques à l'enrichissement, qui traversera tout le programme. Elle montre également comment un raisonnement rigoureux peut être démenti par l'histoire : la révolution industrielle et la transition démographique rompront précisément la relation que Malthus tenait pour nécessaire.",
  'co': "Malthus défend dans l'Essai sur le principe de population (1798) l'idée que la population croît géométriquement quand les subsistances ne croissent qu'arithmétiquement : tout gain de production est donc absorbé par l'accroissement démographique, qui ramène le revenu par tête au niveau de subsistance.",
 },
 "Loi des débouchés : l'offre crée sa propre demande": {
  'af': "Say soutient qu'il ne peut pas exister de crise générale et durable de surproduction, parce que toute production distribue, en se réalisant, les revenus nécessaires à son achat. La thèse, souvent résumée par la formule selon laquelle l'offre crée sa propre demande, repose sur une identité comptable interprétée comme une loi économique : la valeur d'une production est intégralement versée sous forme de salaires, de profits et de rentes, lesquels constituent un pouvoir d'achat d'un montant équivalent. Il en découle que les déséquilibres ne peuvent être que sectoriels — trop de tel bien, trop peu de tel autre — et qu'ils sont corrigés par la variation des prix relatifs, qui réoriente les capitaux vers les productions les plus demandées. Say suppose pour cela que la monnaie n'est qu'un intermédiaire des échanges, intégralement dépensée, hypothèse que Keynes contestera précisément.",
  'po': "Dans le chapitre, la loi des débouchés constitue la clé de voûte de l'édifice classique : elle justifie que l'on puisse raisonner sur l'offre sans se préoccuper de la demande, et fonde la croyance en l'autorégulation des marchés. Elle sert aussi de cible : c'est en la réfutant que Keynes, présenté plus loin, ouvre la macroéconomie moderne.",
  'co': "La loi des débouchés de Jean-Baptiste Say soutient que toute production distribue les revenus permettant de l'acheter : les crises ne peuvent donc être que sectorielles et transitoires, hypothèse qui suppose que la monnaie, simple intermédiaire, soit intégralement dépensée.",
 },
 'Plus-value, exploitation et lutte des classes': {
  'ti': 'Plus-value et exploitation',
  'af': "Marx soutient que le profit capitaliste ne provient ni de l'échange, ni du talent de l'entrepreneur, ni d'une récompense de l'abstinence, mais de l'appropriation d'une plus-value produite par le travail salarié. Sa thèse repose sur une distinction décisive, absente des classiques : celle entre le travail et la force de travail. Ce que le salarié vend n'est pas son travail mais sa capacité de travailler, dont la valeur, comme celle de toute marchandise, est déterminée par le coût de sa reproduction, c'est-à-dire par ce qu'il faut pour l'entretenir et perpétuer sa descendance. Or cette force de travail possède une propriété singulière : mise en œuvre, elle produit une valeur supérieure à la sienne. L'écart entre la valeur créée pendant la journée et la valeur de la force de travail constitue la plus-value, appropriée par le propriétaire des moyens de production. L'exploitation n'est donc ni un vol ni une injustice contractuelle : elle s'opère dans le respect des règles de l'échange.",
  'po': "Dans le chapitre, cette thèse constitue la critique la plus radicale de l'analyse classique, qu'elle attaque de l'intérieur : Marx reprend la théorie de la valeur-travail des classiques et en tire la conclusion inverse de la leur. Elle montre que l'échange marchand, formellement libre et équivalent, peut recouvrir un rapport de domination, et introduit les rapports sociaux dans un raisonnement qui s'en tenait aux grandeurs économiques.",
  'co': "Marx établit dans Le Capital (1867) que le profit provient de la plus-value : le salarié vend sa force de travail à sa valeur de reproduction, mais produit au cours de la journée une valeur supérieure, l'écart étant approprié par le propriétaire des moyens de production dans le respect formel des règles de l'échange.",
 },
 'La condition ouvrière et la critique du capitalisme industriel': {
  'af': "Engels soutient que la misère ouvrière du XIXᵉ siècle n'est pas un retard que le progrès comblerait mais le produit direct de l'industrialisation capitaliste, et que cette thèse doit être établie par l'observation avant d'être théorisée. Sa démarche est celle d'une enquête : il décrit les conditions de logement, d'hygiène, de durée du travail et de mortalité dans les villes industrielles anglaises, et confronte ces observations à la richesse produite au même endroit. La contradiction qu'il met en évidence — la ville la plus riche du monde industriel abritant la population la plus misérable — constitue l'armature de son argumentation. Engels ajoute une thèse proprement politique : la concentration ouvrière créée par l'usine produit simultanément la dégradation des conditions de vie et la possibilité d'une conscience collective, puisque des travailleurs rassemblés dans un même espace découvrent la similitude de leur condition.",
  'po': "Dans le chapitre, cette enquête fournit la base empirique de la critique marxiste et montre que le courant marxiste ne procède pas seulement par déduction. Elle introduit la question sociale dans l'analyse de l'industrialisation et prépare l'étude ultérieure du rapport salarial et de ses transformations.",
  'co': "Dans La situation de la classe laborieuse en Angleterre (1845), Engels documente par l'enquête que la misère ouvrière accompagne la richesse industrielle : la concentration en usine dégrade les conditions de vie tout en rendant possible la formation d'une conscience collective.",
 },
 'Le circuit économique et le produit net': {
  'af': "Quesnay soutient que la richesse ne naît pas de l'échange, comme le croyaient les mercantilistes, mais de la terre, seule activité capable de produire davantage qu'elle ne consomme. Il nomme produit net ce surplus. Sa seconde thèse, plus durable que la première, est méthodologique : l'économie doit être pensée comme un circuit, c'est-à-dire comme un système de flux interdépendants entre groupes sociaux, et non comme une collection d'échanges isolés. Il distingue à cette fin trois classes : la classe productive, qui travaille la terre, la classe des propriétaires, qui perçoit le produit net sous forme de rente, et la classe stérile des artisans et commerçants, qui transforme sans créer de surplus. La reproduction du système exige que le circuit se referme : le produit net dépensé par les propriétaires alimente la demande adressée aux deux autres classes, qui en retour achètent des produits agricoles.",
  'po': "Dans le chapitre, cette analyse marque la naissance du raisonnement macroéconomique : c'est la première tentative de représenter l'économie entière comme un système cohérent de flux. Elle fournit l'ancêtre direct du circuit économique étudié au chapitre 1 et de la comptabilité nationale, et illustre comment une thèse substantielle fausse — la stérilité de l'industrie — peut porter une innovation méthodologique décisive.",
  'co': "Le Tableau économique de Quesnay (1758) constitue la première représentation de l'économie comme circuit : le produit net dégagé par l'agriculture circule entre les trois classes sociales, et la reproduction du système exige que ces flux se referment.",
 },
 "Populationnisme : « il n'est richesse ni force que d'hommes »": {
  'af': "Bodin soutient que la puissance d'un État repose sur le nombre de ses habitants, qui constitue à la fois sa richesse économique et sa force politique et militaire. La thèse s'inscrit dans l'économie pré-industrielle dont elle tire sa cohérence : lorsque la production dépend principalement de la quantité de travail disponible, que la fiscalité repose sur le nombre de contribuables et que la puissance militaire se mesure en soldats, une population nombreuse accroît simultanément les trois dimensions de la puissance. Il en découle un programme politique explicite : encourager la natalité, attirer les artisans étrangers, décourager l'émigration, considérée comme une perte de substance pour le royaume. Cette position populationniste caractérise l'ensemble du courant mercantiliste et sera frontalement renversée deux siècles plus tard par Malthus, pour qui le nombre d'hommes constitue précisément le problème.",
  'po': "Dans le chapitre, cette thèse ouvre la présentation du mercantilisme et montre que la démographie a été pensée comme une variable économique bien avant l'analyse moderne. Elle fournit surtout le contrepoint exact de Malthus, ce qui permet de montrer que la lecture économique de la population dépend entièrement du régime productif considéré.",
  'co': "Pour Jean Bodin, « il n'est richesse ni force que d'hommes » : dans une économie où la production dépend du travail disponible, une population nombreuse accroît simultanément la richesse, les recettes publiques et la puissance militaire.",
 },
 'Colbertisme : manufactures et protectionnisme sélectif': {
  'af': "Colbert soutient que la puissance économique d'un État ne se constate pas mais se construit, et que l'État doit à cette fin créer des industries, les protéger et orienter le commerce. La doctrine s'appuie sur une conception du commerce international comme jeu à somme nulle : le stock mondial de métaux précieux étant donné, l'enrichissement d'une nation suppose qu'elle exporte plus qu'elle n'importe, donc qu'elle capte une part du stock aux dépens des autres. De ce diagnostic découle un ensemble cohérent d'instruments : création de manufactures royales, imposition de normes de qualité destinées à rendre les produits nationaux compétitifs, financement d'infrastructures de transport, développement d'une marine marchande et d'un empire colonial, et protection tarifaire des productions naissantes. L'excédent de la balance commerciale devient ainsi un objectif de politique publique en soi.",
  'po': "Dans le chapitre, le colbertisme représente la première grande doctrine interventionniste et fournit le repoussoir à partir duquel Smith construira son analyse. Il montre aussi que la politique industrielle est une pratique ancienne, ce qui permettra, bien plus loin dans le programme, de situer les débats contemporains sur la souveraineté industrielle dans une histoire longue.",
  'co': "Le colbertisme repose sur une conception du commerce comme jeu à somme nulle : l'État crée des manufactures, impose des normes de qualité, finance les infrastructures et protège les productions naissantes afin de dégager un excédent commercial, érigé en objectif de puissance.",
 },
 'Les vices privés font les bénéfices publics': {
  'af': "Mandeville soutient, sous une forme volontairement provocante, que les comportements moralement condamnables — la vanité, le luxe, la recherche de l'intérêt personnel — soutiennent l'activité économique et profitent à la collectivité, tandis que la vertu et la frugalité l'appauvriraient. La thèse opère une dissociation radicale entre le jugement moral et l'évaluation économique : un comportement peut être blâmable et socialement utile. Le mécanisme invoqué est celui du débouché : la dépense ostentatoire d'une minorité constitue le marché d'une multitude de métiers, l'envie pousse au travail, le luxe fait circuler les revenus. Mandeville en tire une conclusion que le XVIIIᵉ siècle jugera scandaleuse : une société convertie à l'austérité verrait son activité s'effondrer. L'intérêt de cette provocation est qu'elle prépare directement le raisonnement de Smith sur la main invisible, en posant que les motifs individuels n'ont pas à être vertueux pour que le résultat collectif le soit.",
  'po': "Dans le chapitre, cette thèse constitue le chaînon entre la morale religieuse traditionnelle et le libéralisme économique naissant : elle rend pensable l'idée qu'un ordre économique bénéfique puisse résulter de motifs individuels non altruistes, idée que Smith transformera en mécanisme argumenté.",
  'co': "Dans La Fable des abeilles (1714), Mandeville soutient que les vices privés font les bénéfices publics : la dépense ostentatoire et la recherche de l'intérêt personnel alimentent l'activité, ce qui dissocie pour la première fois le jugement moral de l'évaluation économique.",
 },
 'Laissez faire, laissez passer': {
  'af': "La formule attribuée à Vincent de Gournay condense le programme libéral naissant en deux libertés distinctes qu'il ne faut pas confondre : la liberté de produire, qui s'oppose aux privilèges corporatifs et aux réglementations de métier, et la liberté de faire circuler, qui s'oppose aux péages intérieurs, aux prohibitions et aux entraves au commerce des grains. La thèse sous-jacente est que ces entraves empêchent les ressources de se porter là où elles sont le plus utiles : elles maintiennent artificiellement des écarts de prix entre territoires, protègent des positions acquises et créent des pénuries locales au milieu de ressources suffisantes. Les lever permet aux prix de révéler les raretés réelles et aux producteurs de répondre à la demande, sans qu'aucune décision centrale soit nécessaire. La formule n'est donc pas un refus de toute règle mais une position précise sur la nature des règles économiquement nuisibles.",
  'po': "Dans le chapitre, cette formule résume la position physiocratique et libérale et sert de transition entre Quesnay et Smith. Elle permet de montrer que le libéralisme naît comme une critique de réglementations déterminées, et non comme une doctrine abstraite de l'absence d'État.",
  'co': "La formule « laissez faire, laissez passer », attribuée à Vincent de Gournay, condense deux libertés distinctes — produire sans privilège corporatif et circuler sans entrave intérieure — dont la levée permet aux prix de révéler les raretés réelles.",
 },
 'Équilibre général': {
  'af': "Walras soutient que les marchés d'une économie ne peuvent pas être analysés séparément parce qu'ils sont interdépendants, et qu'il existe un système de prix qui les équilibre tous simultanément. La thèse est double. Elle est d'abord substantielle : l'offre et la demande sur un marché dépendent de l'ensemble des prix, puisque chaque agent arbitre entre tous les biens et perçoit des revenus provenant de la vente de ses facteurs ; l'équilibre d'un marché ne peut donc être examiné à prix donnés ailleurs. Elle est ensuite méthodologique : Walras entend faire de l'économie une science déductive et mathématisée, en construisant un système comptant autant d'équations que d'inconnues. Pour montrer comment ce vecteur de prix pourrait être atteint, il imagine le tâtonnement : un commissaire-priseur annonce des prix, recueille les intentions, les ajuste à la hausse là où la demande excède l'offre, et n'autorise les échanges qu'une fois l'équilibre général trouvé.",
  'po': "Dans le chapitre, Walras marque l'entrée dans l'analyse néoclassique et le passage d'une économie politique littéraire à une science formalisée. Son modèle fournit la référence par rapport à laquelle se définiront ensuite toutes les défaillances du marché : chaque hypothèse du tâtonnement qui n'est pas vérifiée dans la réalité désigne un cas d'inefficacité.",
  'co': "Walras établit dans les Éléments d'économie politique pure (1874) l'interdépendance des marchés : l'offre et la demande sur chacun dépendant de tous les prix, l'équilibre ne peut être que général, et la fiction du tâtonnement décrit la procédure par laquelle il serait atteint.",
 },
 'Utilité marginale et révolution marginaliste': {
  'af': "Jevons soutient que la valeur d'un bien ne provient pas du travail qu'il a coûté mais de l'utilité procurée par sa dernière unité consommée, ce qui déplace le fondement de toute l'analyse économique. La thèse résout un problème que les classiques n'avaient pas surmonté, le paradoxe de l'eau et du diamant : l'eau, indispensable, vaut peu, tandis que le diamant, inutile, vaut cher. Le raisonnement marginal le dissout en distinguant l'utilité totale, immense pour l'eau, et l'utilité marginale, très faible parce que l'eau est abondante et que les usages les plus urgents sont déjà satisfaits. La valeur se forme donc à la marge, là où se décide la dernière unité consommée. Jevons en tire la règle de comportement du consommateur : celui-ci répartit son revenu de façon à égaliser l'utilité marginale par unité monétaire dépensée sur tous les biens, faute de quoi il gagnerait à redéployer sa dépense.",
  'po': "Dans le chapitre, cette thèse inaugure le courant néoclassique et marque la rupture théorique la plus profonde du programme : la valeur passe de l'objet produit au sujet qui évalue. Elle fournit le fondement de la théorie du consommateur étudiée au chapitre 4 et s'oppose frontalement à la valeur-travail sur laquelle repose l'analyse marxiste.",
  'co': "Jevons fonde en 1871 le raisonnement marginaliste : la valeur d'un bien est déterminée par l'utilité de sa dernière unité consommée, ce qui dissout le paradoxe de l'eau et du diamant et fait du raisonnement à la marge le cœur de l'analyse économique.",
 },
 'Valeur subjective et individualisme méthodologique': {
  'af': "Menger soutient que la valeur n'est pas une propriété des choses mais un jugement porté par des individus sur l'aptitude d'un bien à satisfaire leurs besoins, et il en tire une méthode pour l'ensemble des sciences sociales. Sa thèse sur la valeur est exigeante : un bien n'a de valeur que si trois conditions sont réunies — un individu éprouve un besoin, il sait que ce bien peut le satisfaire, et il peut effectivement en disposer. La valeur est donc relative aux fins et aux connaissances de chacun et varie d'un individu à l'autre, ce qui interdit de la traiter comme une grandeur objective. De cette position découle l'individualisme méthodologique : les phénomènes collectifs — les prix, la monnaie, les institutions — doivent être expliqués comme des résultats non intentionnels d'actions individuelles, et non par des grandeurs agrégées ou des entités collectives dotées d'une volonté propre.",
  'po': "Dans le chapitre, Menger fonde l'école autrichienne et introduit l'opposition méthodologique majeure du programme : l'individualisme méthodologique, qui explique le social par les individus, face au holisme durkheimien, qui explique les faits sociaux par le social. Cette opposition structurera l'ensemble de la sociologie étudiée en seconde partie d'année.",
  'co': "Carl Menger fonde la valeur sur le jugement subjectif des individus et en déduit l'individualisme méthodologique : les phénomènes collectifs comme la monnaie ou les prix doivent être expliqués comme des résultats non intentionnels d'actions individuelles.",
 },
 'IS-LM et synthèse keynésienne': {
  'af': "Hicks soutient que l'analyse de Keynes peut être traduite dans un cadre formel articulant le marché des biens et le marché de la monnaie, ce qui permet de déterminer simultanément le revenu et le taux d'intérêt et de discuter rigoureusement l'efficacité des politiques économiques. La courbe IS rassemble les couples de revenu et de taux pour lesquels le marché des biens est équilibré : un taux plus bas stimule l'investissement, donc le revenu, d'où sa pente décroissante. La courbe LM rassemble ceux pour lesquels le marché de la monnaie l'est : un revenu plus élevé accroît la demande de monnaie de transaction et élève le taux, d'où sa pente croissante. Leur intersection détermine l'équilibre global. La portée du dispositif est qu'il rend discutables, dans un même cadre, des questions jusque-là séparées : l'effet d'éviction d'une relance budgétaire, l'inefficacité de la politique monétaire en trappe à liquidité, et les conditions d'un policy mix cohérent.",
  'po': "Dans le chapitre, Hicks représente la synthèse néoclassique, c'est-à-dire la tentative d'intégrer l'apport keynésien dans le cadre formel néoclassique. Il illustre un mouvement important de l'histoire de la pensée : une théorie ne s'impose qu'en se laissant formaliser, au prix souvent de l'abandon de certains de ses éléments, ici l'incertitude radicale et les anticipations conventionnelles.",
  'co': "Le modèle IS-LM, proposé par Hicks en 1937, détermine simultanément le revenu et le taux d'intérêt à partir de l'équilibre du marché des biens et de celui de la monnaie : il permet de discuter l'effet d'éviction, la trappe à liquidité et la cohérence du policy mix.",
 },
 'Consommation ostentatoire': {
  'af': "Veblen soutient que la consommation n'obéit pas seulement à la satisfaction de besoins mais à une logique de distinction sociale : on consomme pour signifier sa position. Sa thèse part d'une observation historique : dans une société où le statut n'est plus garanti par la naissance, il doit être continuellement démontré, et la dépense visible et inutile constitue précisément le meilleur signal, parce qu'elle est coûteuse donc difficile à imiter. Il en résulte des comportements que la théorie standard ne prévoit pas. La demande de certains biens augmente avec leur prix, puisque c'est le prix qui fait le signal : c'est l'effet Veblen. Et la diffusion d'un marqueur de statut vers les classes moyennes contraint les groupes dominants à en adopter de nouveaux, ce qui engendre un mouvement permanent de renouvellement des signes plutôt qu'une convergence des consommations.",
  'po': "Dans le chapitre, Veblen représente le courant institutionnaliste et introduit une critique du modèle de l'homo œconomicus qui ne vient ni du marxisme ni du keynésianisme : la rationalité du consommateur n'est pas contestée, c'est l'objet de ses préférences qui est socialement construit. Cette analyse prépare l'étude de la consommation comme fait social.",
  'co': "Dans la Théorie de la classe de loisir (1899), Veblen montre que la consommation ostentatoire sert de marqueur de statut : la dépense visible et coûteuse fonctionne comme un signal de position sociale, ce qui explique que la demande de certains biens croisse avec leur prix.",
 },
 'Régulation : le capitalisme comme système historique': {
  'af': "Aglietta soutient que le capitalisme n'est pas un mécanisme intemporel régi par des lois constantes mais une succession de régimes historiques, chacun soutenu par un ensemble d'institutions, et que les crises marquent l'épuisement d'un régime plutôt qu'un accident conjoncturel. Sa thèse repose sur la notion de régime d'accumulation : une configuration cohérente associant une forme de concurrence, un rapport salarial, un régime monétaire, un rôle de l'État et un mode d'insertion internationale. Tant que ces éléments sont ajustés les uns aux autres, la croissance est régulière et les conflits sont canalisés. Lorsque la cohérence se défait — parce que les gains de productivité ne suffisent plus à nourrir le compromis salarial, ou parce que l'ouverture internationale défait le rapport salarial national — la crise devient structurelle et ne peut être résolue par les instruments conjoncturels : elle appelle un nouveau compromis institutionnel.",
  'po': "Dans le chapitre, l'école de la régulation représente une voie intermédiaire entre l'analyse marxiste, dont elle retient les contradictions structurelles, et l'analyse néoclassique, dont elle retient l'attention aux mécanismes de marché. Elle fournit surtout un outil de périodisation qui permettra d'analyser le fordisme puis sa crise.",
  'co': "Pour Aglietta et l'école de la régulation, le capitalisme se déploie en régimes d'accumulation successifs, soutenus par un ensemble cohérent d'institutions : les crises majeures signalent l'épuisement de cette cohérence et appellent un nouveau compromis institutionnel plutôt qu'un simple ajustement conjoncturel.",
 },
 'Mode de régulation et cohérence institutionnelle': {
  'af': "Boyer soutient qu'il n'existe pas un capitalisme mais des capitalismes, et que la performance d'une économie dépend moins de la qualité de chaque institution prise isolément que de leur cohérence d'ensemble. Sa thèse repose sur la notion de complémentarité institutionnelle : cinq formes institutionnelles — le rapport salarial, la forme de la concurrence, le régime monétaire, le rôle de l'État et l'insertion internationale — se soutiennent mutuellement, de sorte qu'une configuration peut être performante alors même que chacune de ses composantes, évaluée séparément, paraîtrait sous-optimale. La conséquence pratique est importante et contre-intuitive : transplanter un élément d'un modèle dans un autre dégrade l'ensemble, parce que l'élément importé perd les institutions qui le rendaient efficace. Il n'existe donc pas de réforme universellement bonne, mais des réformes cohérentes avec une configuration donnée.",
  'po': "Dans le chapitre, Boyer systématise le programme régulationniste et fournit l'argument théorique contre l'idée d'un modèle économique unique. Cette thèse de la pluralité des capitalismes sera réemployée tout au long du programme, sur les stratégies de développement comme sur les comparaisons de modèles productifs nationaux.",
  'co': "Robert Boyer montre que les institutions économiques forment un système de complémentarités : une configuration cohérente peut être performante alors que chacune de ses composantes paraîtrait isolément sous-optimale, ce qui condamne les réformes importées d'un modèle étranger.",
 },
 'Optimum de Pareto': {
  'af': "Pareto propose un critère d'évaluation des situations économiques qui ne suppose aucune comparaison des satisfactions entre individus : une allocation est optimale lorsqu'il est impossible d'améliorer la situation de l'un sans détériorer celle d'un autre. La thèse associée est que l'équilibre concurrentiel atteint un tel optimum. Mais la portée exacte du critère doit être mesurée, car elle est à la fois forte et très limitée. Elle est forte parce qu'elle fournit un étalon objectif, indépendant de tout jugement de valeur sur la répartition. Elle est limitée pour exactement la même raison : le critère ne se prononce que sur les améliorations unanimes et reste donc muet sur la distribution. Une situation où une personne détient tout est Pareto-optimale, puisqu'on ne peut rien donner à autrui sans la léser. Pareto établit ainsi que l'efficacité et la justice sont deux questions distinctes, et que la première ne préjuge en rien de la seconde.",
  'po': "Dans le chapitre, ce critère achève la construction néoclassique en lui donnant son instrument d'évaluation. Il est aussi l'un des outils les plus utiles du programme, parce qu'il permet de formuler précisément la limite de l'argument libéral : démontrer qu'un marché est efficace ne démontre pas qu'il est juste.",
  'co': "L'optimum de Pareto définit une allocation telle qu'on ne peut améliorer la situation d'un agent sans détériorer celle d'un autre : ce critère établit l'efficacité de l'équilibre concurrentiel mais reste par construction muet sur l'équité de la répartition.",
 },
 "Équilibre général et théorème d'impossibilité": {
  'ti': 'Équilibre général Arrow-Debreu : les conditions de validité',
  'af': "Arrow, avec Debreu, démontre rigoureusement qu'un équilibre général concurrentiel existe, mais la portée de ce résultat tient autant aux hypothèses qu'il exige qu'à la conclusion qu'il établit. Les conditions requises sont en effet d'une sévérité remarquable : il faut que les marchés soient complets, c'est-à-dire qu'il existe un marché pour chaque bien, à chaque date et dans chaque état futur du monde ; que l'information soit parfaite ; qu'il n'y ait ni rendements croissants, ni externalités, ni pouvoir de marché. La thèse de fond est donc double et souvent mal restituée : la démonstration confirme l'intuition libérale d'une coordination efficace par les prix, mais elle en délimite exactement le domaine de validité. Chaque hypothèse absente de la réalité constitue une défaillance de marché identifiée, ce qui fait de ce théorème le fondement théorique de l'analyse des défaillances étudiée au chapitre 5.",
  'po': "Dans le chapitre, ce résultat achève la formalisation de l'analyse néoclassique et montre en même temps sa limite interne. Il fournit un argument d'une grande force : ce n'est pas une critique extérieure mais la théorie elle-même, portée à son plus haut degré de rigueur, qui circonscrit la portée du résultat libéral.",
  'co': "Le théorème d'existence d'Arrow et Debreu démontre qu'un équilibre général concurrentiel existe, mais sous des hypothèses très restrictives — marchés complets, information parfaite, absence d'externalités et de rendements croissants : chaque hypothèse manquante dans la réalité constitue une défaillance de marché.",
 },
}

